import { defineConfig } from 'vitest/config'
import react from '@vitejs/plugin-react'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

// HTTPS in development: reuse the self-signed certificate generated by
// `python -m app.cli gen-cert` (backend/certs). Falls back to HTTP if absent.
const certDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../backend/certs')
const keyFile = path.join(certDir, 'localhost-key.pem')
const certFile = path.join(certDir, 'localhost.pem')
const hasCert = fs.existsSync(keyFile) && fs.existsSync(certFile)

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    https: hasCert ? { key: fs.readFileSync(keyFile), cert: fs.readFileSync(certFile) } : undefined,
    proxy: {
      '/api': {
        target: hasCert ? 'https://localhost:8000' : 'http://localhost:8000',
        secure: false,
        changeOrigin: true,
      },
    },
  },
  build: { chunkSizeWarningLimit: 1600 },
  test: {
    environment: 'jsdom',
    setupFiles: './src/test/setup.ts',
    globals: true,
  },
})
